document.addEventListener('click',e=>{const t=e.target.closest&&e.target.closest('[data-act]');if(!t)return;e.preventDefault();const f={logout:()=>logout(),exportData:()=>exportData(),installApp:()=>installApp()}[t.dataset.act];if(f)f()});
const $=s=>document.querySelector(s),app=$('#app');let me={user:null};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api=async(p,m='GET',b)=>{const r=await fetch('/api'+p,{method:m,headers:{'content-type':'application/json'},body:b?JSON.stringify(b):undefined});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'حدث خطأ');return j};
const toast=(m,e)=>{const t=document.createElement('div');t.className='toast'+(e?' err':'');t.textContent=m;document.body.append(t);setTimeout(()=>t.remove(),3500)};
const sub=f=>async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));e.target.querySelectorAll('[type=checkbox]').forEach(c=>b[c.name]=c.checked);try{await f(b,e.target)}catch(x){toast(x.message,1)}};
const ST={draft:'مسودة',published:'منشور',negotiating:'جارٍ الاتفاق',helper_chosen:'تم اختيار مساعد',in_progress:'قيد التنفيذ',completed:'مكتمل',cancelled:'ملغي',disputed:'متنازع عليه'};
const stat=s=>`<span class="pill s-${s}">${ST[s]||s}</span>`;
const price=r=>r.budget!=null&&r.budget!==''?r.budget+' ر.س'+(r.negotiable?' (قابل للتفاوض)':''):'السعر بالاتفاق';
const ic=(p,c='')=>`<svg class="ic ${c}" viewBox="0 0 24 24" aria-hidden="true">${p}</svg>`;
const I={feed:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M7 8h10M7 12h10M7 16h6"/>',chev:'<path d="M9 6l6 6-6 6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',search:'<circle cx="11" cy="11" r="7"/><path d="M20 20l-4-4"/>',filter:'<path d="M4 7h10M18 7h2M4 17h4M12 17h8"/><circle cx="16" cy="7" r="2"/><circle cx="10" cy="17" r="2"/>',bell:'<path d="M6 16V11a6 6 0 0 1 12 0v5l2 2H4z"/><path d="M10 21h4"/>',pin:'<path d="M12 21s-7-6.2-7-11a7 7 0 0 1 14 0c0 4.8-7 11-7 11z"/><circle cx="12" cy="10" r="2.5"/>',clip:'<path d="M21 11l-8.5 8.5a5 5 0 0 1-7-7L14 4a3.5 3.5 0 0 1 5 5l-8.5 8.5a2 2 0 0 1-3-3L15 7"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',more:'<circle cx="5" cy="12" r="1.6"/><circle cx="12" cy="12" r="1.6"/><circle cx="19" cy="12" r="1.6"/>'};
const CATS={'أخرى':'<path d="M12 3l1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8z"/>'};
const pr=r=>r.budget!=null&&r.budget!==''?r.budget+' ريال':'بالاتفاق';
const card=r=>`<article class=card><div class=thumb>${r.image_id?`<img loading=lazy decoding=async src=/api/files/${r.image_id} alt="">`:`<span class=thumb-ic>${ic(CATS[r.category]||CATS['أخرى'],'big')}</span>`}${r.category?`<span class=tag>${esc(r.category)}</span>`:''}</div><div class=cb><div class=row>${stat(r.status)}<small>${new Date(r.created_at.replace(' ','T')+'Z').toLocaleDateString('ar-SA-u-ca-gregory')}</small></div><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p><div class=meta-l>${r.city?`<span>${ic(I.pin)} ${esc(r.city)}</span>`:''}<span>${r.offers} عروض</span></div><div class=cf><span class=who><i class=av>${esc([...r.owner][0])}</i>${esc(r.owner)}</span><span class=price>${pr(r)}</span></div><a class="btn full" href="#/r/${r.id}">عرض التفاصيل</a></div></article>`;
function renderBottom(){const bn=$('#bn');if(bn)bn.innerHTML=''}
async function exportData(){try{const d=await api('/me/export');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.download='my-data.json';document.body.append(a);a.click();a.remove();toast('تم تجهيز ملف بياناتك')}catch(x){toast(x.message,1)}}
function toggleMenu(){const m=$('#menu');m.hidden=!m.hidden}
function closeMenu(){const m=$('#menu');if(m)m.hidden=true}
document.addEventListener('click',e=>{if(e.target.closest('#mb,#hmb')){toggleMenu();return}if(!e.target.closest('#menu'))closeMenu()});
function nav(){const u=me.user,h=location.hash||'#/',a=(l,t)=>`<a href="${l}" class="${h===l?'on':''}">${t}</a>`;
$('#nav').innerHTML=`<a class=logo href="#/"><span class=mark><img loading=lazy decoding=async src=/hand.png alt=""></span>المساعد</a><div class=hact>${u?`<a class=bell href="#/notifs" aria-label="الإشعارات">${ic(I.bell)}${me.unread?'<i class=dot></i>':''}</a>`:'<a class=hlogin href="#/login">تسجيل الدخول</a>'}<button id=mb aria-label="القائمة">${ic(I.menu)}</button></div>`;
$('#menu').innerHTML=a('#/','المساعد الذكي')+a('#/feed','المنشورات العامة')+(isStandalone()?'':'<a href="#" data-act=installApp>تثبيت التطبيق</a>')+(u?a('#/chats','محادثاتي')+a('#/profile','حسابي')+(['admin','staff'].includes(u.role)?a('#/manage','الإدارة'):''):'')+a('#/complaints','سياسة الشكاوى')+a('#/about','من نحن')+a('#/contact','تواصل معنا')+a('#/terms','الشروط والأحكام')+a('#/privacy','سياسة الخصوصية')+(u?'<a href="#" data-act="exportData">تصدير بياناتي</a><a href="#/settings">الإعدادات</a><a href="#/profile">حذف حسابي</a>':'')+(u?'<a href="#" data-act="logout">تسجيل الخروج</a>':a('#/login','دخول / تسجيل'));
renderBottom(h);$('#menu').onclick=e=>{if(e.target.tagName==='A')closeMenu()}}
async function insights(){location.hash='#/manage/insights'}
async function drawInsights(){$('#mgBody').innerHTML=`<section class=panel><div class=sec-h><h3>تحليل الطلب</h3></div><div class=seg id=idays><button data-d=7>7 أيام</button><button data-d=30>30 يومًا</button><button data-d=0>الكل</button></div><div class=seg id=itabs><button data-t=demand>الأكثر طلبًا</button><button data-t=gap>الفجوة</button><button data-t=failed>بحث بلا نتيجة</button></div><div id=ibody></div></section>`;
const st={d:30,t:'demand'};const tbl=(h,rows)=>`<div class=tbl-wrap><table class=tbl><tr>${h.map(x=>`<th>${esc(x)}</th>`).join('')}</tr>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')||`<tr><td colspan=${h.length}>لا توجد بيانات في هذه الفترة.</td></tr>`}</table></div>`;
const paint=async()=>{document.querySelectorAll('#idays button').forEach(b=>b.classList.toggle('on',+b.dataset.d===st.d));document.querySelectorAll('#itabs button').forEach(b=>b.classList.toggle('on',b.dataset.t===st.t));
try{const r=await api('/admin/insights?days='+st.d);const note=r.total<10?`<div class=notice>عدد الطلبات في هذه الفترة ${r.total} فقط، والأرقام لا تكفي لاستنتاج واضح.</div>`:'';
let body='';if(st.t==='demand')body=tbl(['التخصص','القسم','عدد الطلبات'],r.demand.map(x=>[x.name,x.cat,x.n]));
else if(st.t==='gap')body=tbl(['التخصص','القسم','الطلبات','المساعدون المسجلون','ملاحظة'],r.gap.map(x=>[x.name,x.cat,x.n,x.helpers,x.n>=3&&x.helpers<=1?'فجوة: طلب كثير ومساعدون قليلون':'']));
else body=tbl(['العبارة','التكرار','آخر مرة'],r.failed.map(x=>[x.text,x.n,String(x.last).slice(0,10)]));
$('#ibody').innerHTML=note+body}catch(x){$('#ibody').innerHTML=`<div class=empty>${esc(x.message)}</div>`}};
document.querySelectorAll('#idays button').forEach(b=>b.onclick=()=>{st.d=+b.dataset.d;paint()});
document.querySelectorAll('#itabs button').forEach(b=>b.onclick=()=>{st.t=b.dataset.t;paint()});paint()}

async function home(){const feedBtn=`<a class=hbtn href="#/feed" aria-label="المنشورات العامة">${ic(I.feed)}</a>`;const bell=me.user?`<a class=hbtn href="#/notifs" aria-label="الإشعارات">${ic(I.bell)}${me.unread?'<i class=dot></i>':''}</a>`:'<span class=hbtn></span>',avatar=`<button class=hbtn id=hmb type=button aria-label="القائمة">${ic(I.menu)}</button>`;
app.innerHTML=`<section class=chat-wrap><div class=chat-top><div class=ctitle><img loading=lazy decoding=async class=ctl-logo src=/hand.png alt=""><div><b>منصة المساعد</b><small>خدمتك تبدأ من هنا</small></div></div><div class=ctl-actions>${feedBtn}${bell}${avatar}</div></div><div id=msgs class=chat-msgs aria-live=polite></div><div class=sugs>${['أبي سباك يصلح تسريب مياه','أبي كهربائي يصلح قاطع الكهرباء'].map(s=>`<button type=button class=sug>${esc(s)}</button>`).join('')}</div><form id=cf class=chat-in><input name=m maxlength=500 required placeholder="اكتب رسالتك هنا..." aria-label="اكتب رسالتك"><button class=send aria-label="إرسال"><svg class=ic viewBox="0 0 24 24" aria-hidden="true"><path d="M22 2L11 13M22 2l-7 20-4-9-9-4z"/></svg></button></form></section>`;
const msgs=$('#msgs'),now=()=>new Date().toLocaleTimeString('ar',{hour:'2-digit',minute:'2-digit'});
const bot=(html)=>{const r=document.createElement('div');r.className='brow';r.innerHTML=`<img loading=lazy decoding=async class=bav src=/hand.png alt=""><div class=bcol><div class="bub b">${html}</div><small class=btime>${now()}</small></div>`;msgs.append(r);msgs.scrollTop=msgs.scrollHeight;return r};
const user=(text)=>{const r=document.createElement('div');r.className='urow';r.innerHTML=`<div class=bcol><div class="bub u">${esc(text)}</div><small class=btime>${now()}</small></div>`;msgs.append(r);msgs.scrollTop=msgs.scrollHeight};
bot('<b>مرحبًا بك في منصة المساعد</b><br>أستطيع إيجاد الشخص المناسب من مقدمي الخدمات المسجلين في المنصة.<br><br>اكتب طلبك أو اختر من الأمثلة أدناه.');
const ask=async text=>{user(text);const w=bot('<span class=wait>جاري البحث عن المتاحين في المنصة</span><span class=typing><span></span><span></span><span></span></span>');
try{const r=await api('/assistant','POST',{message:text});w.remove();
bot(esc(r.reply)+(r.needLogin?'<div class=row style="margin-top:8px"><a class=btn href="#/login">سجّل دخولك</a></div>':''));
if(r.providers&&r.providers.length){const card=document.createElement('div');card.className='urow';card.innerHTML=`<div class=sumcard><div class=grow><b>لقد وجدت لك ${r.providers.length} مساعدًا مسجلًا في المنصة</b><small>يمكنك مراجعة ملفاتهم والتواصل معهم عبر طلب، أو العودة للمحادثة لمزيد من التفاصيل.</small></div>${ic(I.user)}</div>`;msgs.append(card);
r.providers.forEach(p=>bot(`<div class=pwrap><a class=pcard href="#/p/${p.id}"><img class=pcard-logo src="/logo.png" alt="شعار المساعد" width=48 height=48 loading=lazy decoding=async><div class=grow><b>${esc(p.name)}</b><small>${esc(p.city||'')} · أنجز ${p.done} مهمة</small><div class=pstats><span class=pstat>${p.rcount?`★ ${esc(p.avg)} <em>(${p.rcount} تقييم)</em>`:'<em>لا توجد تقييمات بعد</em>'}</span><span class=pstat>♥ ${p.likes} إعجاب</span></div></div>${ic(I.chev)}</a><a class="btn alt" href="#/direct/${p.id}">محادثة</a></div>`))}
if(r.noMatch){if(r.sections&&r.sections.length){const b=bot('<div>لم نجد الخدمة بالضبط، اختر التخصص الأقرب لطلبك:</div><form class=sec-pick style="display:grid;gap:8px;margin-top:8px"><select name=sec required style="padding:10px;border-radius:10px;border:1px solid #d1d5db;font:inherit"><option value="">اختر التخصص</option>'+r.sections.map(x=>`<option value="${esc(x.name)}">${esc(x.name)}</option>`).join('')+'</select><button class=btn>بحث</button></form>');const f=b.querySelector('.sec-pick');f.onsubmit=e=>{e.preventDefault();const v=f.sec.value;if(!v)return;f.remove();ask(v)}}bot('<a class=btn href="#/profile">اقترح قسمًا لخدمتك</a>')}

msgs.scrollTop=msgs.scrollHeight}
catch(x){w.remove();bot(`<span style="color:#8a2b1c">${esc(x.message||'حدث خطأ، حاول مرة أخرى.')}</span>`)}};
$('#cf').onsubmit=e=>{e.preventDefault();const v=e.target.m.value.trim();if(v.length<3){toast('اكتب طلبك في جملة واضحة',1);return}e.target.m.value='';ask(v)};
document.querySelectorAll('.sug').forEach(b=>b.onclick=()=>ask(b.textContent));}
const CAT_ICO=['🚿','⚡','❄️','🪑','🔩','🎨','🧹','🪳','🚚','💻','🖌️','📣','📷','🧾','🗂️','🖊️','🎓','🏠','🌿','🚗','🛞','🎉','🍽️','🧵','💅','🏋️','🏢','⚖️','📱','🛡️','👶','🧓','📦','🖨️','☀️','💧','✈️','🐾','⚓','🚨','🛒','🏛️'];
const specBoxes=(cats,sel=[])=>`<input class=cat-q type=search placeholder="ابحث عن قسم..." aria-label="ابحث عن قسم">`+cats.map((c,i)=>`<label class=cat-card data-n="${esc(c.name)}"><input type=radio name=cat value=${c.id}${sel.includes(c.id)?' checked':''}><span class=cat-ic aria-hidden=true>${CAT_ICO[i]||'🔹'}</span><b>${esc(c.name)}</b><span class=cat-dot aria-hidden=true></span></label>`).join('');
const specLimit=e=>{const box=e.currentTarget;const n=[...box.querySelectorAll('details')].filter(d=>d.querySelector('input:checked')).length;if(n>3){e.target.checked=false;toast('يمكن اختيار تخصصات من 3 أقسام كحد أقصى',1)}};
function auth(reg){const CITIES=['الرياض','جدة','مكة','المدينة','الدمام','الخبر','الطائف','تبوك','أبها','بريدة','حائل','القصيم','الجبيل','ينبع'];
const head=`<div class=auth-head><span class=mark-lg><img loading=lazy decoding=async src=/hand.png alt=""></span><h1>${reg?'إنشاء حساب جديد':'أهلًا بعودتك'}</h1><p>${reg?'سجّل في دقيقة وابدأ تطلب المساعدة أو تقدّمها.':'سجّل دخولك لمتابعة طلباتك ومحادثاتك.'}</p></div>`;
const regFields=`<label>اسم المستخدم<input name=name required minlength=2 autocomplete=username placeholder="اسم المستخدم"></label><label>رقم الجوال<input name=phone type=tel dir=ltr inputmode=tel required placeholder="05XXXXXXXX"></label>`;


const pwField=`<label>كلمة المرور<span class=pw-wrap><input name=password type=password minlength=8 required autocomplete=${reg?'new-password':'current-password'} dir=ltr${reg?' placeholder="8 أحرف على الأقل"':''}><button type=button class=pw-eye id=pwe aria-label="إظهار كلمة المرور">عرض</button></span></label>`;
const app2=`<section class=auth>${head}<form id=a class=auth-form>${reg?regFields:''}<label>البريد الإلكتروني<input name=email type=email required autocomplete=email dir=ltr placeholder="name@example.com"></label>${pwField}${reg?'<label>تأكيد كلمة المرور<input name=confirm type=password minlength=8 required autocomplete=new-password dir=ltr></label>':''}${reg?'<label class=check><input type=checkbox name=age required> عمري 18 سنة فأكثر</label>':''}${reg?'<label class=check><input type=checkbox name=terms required> أوافق على <a href="#/terms">الشروط</a> و<a href="#/privacy">سياسة الخصوصية</a>، وأقر بأن المنصة وسيط تقني فقط ولا تتحمل مسؤولية الاتفاقات بين الأطراف</label>':''}<button class=btn>${reg?'التالي':'دخول'}</button></form><p class=auth-alt>${reg?'لديك حساب؟ <a href="#/login">سجّل دخولك</a>':'ليس لديك حساب؟ <a href="#/register">أنشئ حسابًا</a>'}</p>${reg?'':'<p class=auth-alt><a href="#/forgot">نسيت كلمة المرور؟</a></p>'}</section>`;
app.innerHTML=app2;
if(!reg){const ab=document.createElement('button');ab.type='button';ab.className='btn alt sm';ab.id='admB';ab.style.marginTop='12px';ab.textContent='دخول الإدارة';ab.onclick=()=>{const f=$('#a');window.__postLogin='#/manage';if(!f.reportValidity()){window.__postLogin=null;return}f.requestSubmit()};$('.auth-form').insertAdjacentElement('afterend',ab)}
$('#pwe').onclick=()=>{const p=$('#a input[name=password]');const show=p.type==='password';p.type=show?'text':'password';$('#pwe').textContent=show?'إخفاء':'عرض'};


$('#a').onsubmit=sub(async b=>{if(reg){if(b.password!==b.confirm)throw new Error('كلمتا المرور غير متطابقتين');delete b.confirm;await api('/register','POST',b);await boot();location.hash='#/verify-email';return}await api('/login','POST',b);await boot();const nx=window.__postLogin||'#/';window.__postLogin=null;location.hash=nx})}
function DCHAT_MARKUP(){return `<section class=panel id=dchat><h3 style="margin-top:0">محادثة مباشرة</h3><small>للاستفسار قبل الطلب. إثبات التحويل والدفع يكون داخل الطلب فقط.</small><div id=dagr class=agr></div><form id=aform class=agr-form><small>اقترح اتفاقًا على الخدمة والمبلغ، ولا يُعد الاتفاق نافذًا حتى يوافق الطرف الآخر.</small><input name=description maxlength=300 placeholder="وصف الخدمة، مثل: تركيب باب" aria-label="وصف الخدمة" required><input name=amount type=number min=1 max=100000 placeholder="المبلغ بالريال" aria-label="المبلغ" required><button class=btn>اقترح الاتفاق</button></form><div id=dmsgs class=dmsgs></div><form id=dform class=row style="gap:8px"><input name=body maxlength=1000 placeholder="اكتب استفسارك" aria-label="اكتب استفسارك" style="flex:1"><button type=button class="btn alt" id=dpic aria-label="إرفاق صورة">${ic(I.clip)}</button><button class=btn>إرسال</button></form></section>`}
async function directChat(id){if(!me.user){location.hash='#/login';return}const peer=await api('/users/'+id).catch(()=>null);const name=(peer&&peer.name)||'المستخدم';app.innerHTML=`<section class=panel style="padding-bottom:6px"><div class=row><h3 style="margin:0">محادثة مع ${esc(name)}</h3><a class=lnk href="#/p/${id}">عرض الملف</a></div></section>`+DCHAT_MARKUP();dchatInit(id)}
async function chats(){const l=await api('/chats');app.innerHTML=`<h2 style="margin:8px 0">صندوق الوارد</h2><div class=panel style="padding:0">${l.map(c=>{const href=c.request_id?`#/chat/${esc(c.request_id)}/${esc(c.peer)}`:`#/direct/${esc(c.peer)}`;const t=String(c.created_at||'');return `<a href="${href}" style="display:flex;align-items:center;gap:12px;padding:12px 14px;border-bottom:1px solid #eef0f2;text-decoration:none;color:inherit"><i style="width:52px;height:52px;border-radius:50%;background:#0f6b4f;color:#fff;display:grid;place-items:center;font-style:normal;font-weight:700;flex:0 0 auto">${esc((c.peer_name||'؟')[0])}</i><span style="flex:1;min-width:0"><b>${esc(c.peer_name)}</b><small style="display:block;color:#6b7280;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(c.title||'')}${c.body?' · '+esc(c.body.slice(0,50)):''}</small></span><small style="color:#9ca3af;flex:0 0 auto">${esc(t.slice(11,16))}</small></a>`}).join('')||'<div class=empty style="padding:20px">لا توجد محادثات بعد. تبدأ المحادثة من صفحة المساعد.</div>'}</div>`}
const askKind=()=>new Promise(ok=>{const o=document.createElement('div');o.style.cssText='position:fixed;inset:0;background:#0008;z-index:50;display:grid;place-items:end center';o.innerHTML='<div style="background:#fff;width:100%;max-width:480px;border-radius:20px 20px 0 0;padding:18px;display:grid;gap:10px;direction:rtl"><b>أين تريد نشر هذا المقطع؟</b><button class=btn type=button data-k=reel>ريلز (يظهر للجميع)</button><button class="btn alt" type=button data-k=post>منشور (يظهر للجميع)</button></div>';o.onclick=e=>{const k=e.target.dataset&&e.target.dataset.k;if(k||e.target===o){o.remove();ok(k||null)}};document.body.append(o)});
const accTabs=pics=>{const posts=pics.filter(x=>x.kind!=='reel'),reels=pics.filter(x=>x.kind==='reel'),tl=a=>a.map(x=>`<figure>${mediaTag(x)}${x.caption?`<figcaption>${esc(x.caption)}</figcaption>`:''}</figure>`).join('');return `<div class=acc-tabs><nav><button type=button class=on data-tab=posts>المنشورات</button><button type=button data-tab=reels>ريلز</button></nav><div class=acc-grid id=tg-posts>${tl(posts)}<button class=acc-add id=addWork type=button aria-label="إضافة صورة أو فيديو">+</button>${posts.length?'':'<div class=acc-empty>لم تضف أعمالًا بعد. ابدأ بإضافة صورة لعملك.</div>'}</div><div class=acc-grid id=tg-reels hidden>${tl(reels)}<button class=acc-add id=addWork2 type=button aria-label="إضافة ريلز">+</button>${reels.length?'':'<div class=acc-empty>لا توجد ريلز بعد. ارفع فيديو واختر «ريلز».</div>'}</div></div>`};
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-tab]');if(!b)return;document.querySelectorAll('.acc-tabs nav [data-tab]').forEach(x=>x.classList.toggle('on',x===b));const r=b.dataset.tab==='reels';const g1=document.getElementById('tg-posts'),g2=document.getElementById('tg-reels');if(g1)g1.hidden=r;if(g2)g2.hidden=!r});
const pickMedia=()=>new Promise((ok,no)=>{const i=document.createElement('input');i.type='file';i.accept='image/*,video/mp4,video/quicktime,video/webm';i.onchange=()=>{const f=i.files[0];if(!f)return no(new Error('لم تختر ملفًا'));pickMedia.last=f.type||(/\.(mov|mp4|webm)$/i.test(f.name)?'video/x':'');if(f.type.startsWith('video/')){(async()=>{try{const mime=f.type||(/\.mov$/i.test(f.name)?'video/quicktime':'video/mp4');const r0=await api('/upload-video/init','POST',{mime,size:f.size});if(r0.mode==='disk'){if(f.size>30e6)throw new Error('حجم الفيديو يجب ألا يتجاوز 30 ميجابايت');const rr=await fetch('/api/upload-raw',{method:'POST',headers:{'content-type':'application/octet-stream','x-video-mime':mime},body:f});const j=await rr.json().catch(()=>({}));if(!rr.ok)throw new Error(j.error||'تعذّر رفع الفيديو');return ok(j.id)}
if(r0.mode==='external'){const put=await fetch(r0.url,{method:'PUT',headers:{'content-type':mime},body:f});if(!put.ok)throw new Error('تعذّر رفع الفيديو، حاول مرة أخرى');const c=await api('/upload-video/complete','POST',{key:r0.key,mime});return ok(c.id)}if(f.size>8e6)throw new Error('حجم الفيديو يجب ألا يتجاوز 8 ميجابايت');const data=await new Promise((res,rej)=>{const rd=new FileReader();rd.onload=()=>res(rd.result);rd.onerror=()=>rej(new Error('تعذّر قراءة الفيديو'));rd.readAsDataURL(f)});const x=await api('/upload-video','POST',{data});ok(x.id)}catch(e){no(e)}})();return}const im=new Image();im.onload=()=>{const k=Math.min(1,1280/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=im.width*k;c.height=im.height*k;c.getContext('2d').drawImage(im,0,0,c.width,c.height);api('/upload','POST',{data:c.toDataURL('image/jpeg',.8)}).then(r=>ok(r.id),no)};im.onerror=()=>no(new Error('الملف ليس صورة'));im.src=URL.createObjectURL(f)};i.click()});
const pick=()=>new Promise((ok,no)=>{const i=document.createElement('input');i.type='file';i.accept='image/*';i.onchange=()=>{const f=i.files[0];if(!f)return no(new Error('لم تختر صورة'));const im=new Image();im.onload=()=>{const k=Math.min(1,1280/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=im.width*k;c.height=im.height*k;c.getContext('2d').drawImage(im,0,0,c.width,c.height);api('/upload','POST',{data:c.toDataURL('image/jpeg',.8)}).then(r=>ok(r.id),no)};im.onerror=()=>no(new Error('الملف ليس صورة'));im.src=URL.createObjectURL(f)};i.click()});
document.addEventListener('click',async e=>{const t=e.target.closest&&e.target.closest('#addWork,#addWork2,#addPh,#avEdit,#avDel');if(!t)return;e.preventDefault();try{if(t.id==='avDel'){if(!confirm('حذف الصورة الشخصية؟'))return;await api('/me/avatar/delete','POST');toast('تم حذف الصورة الشخصية')}else if(t.id==='avEdit'){const id=await pick();await api('/me/avatar','POST',{attachment_id:id});toast('تم تحديث الصورة الشخصية')}else{const id=await pickMedia();let kind='post';if(/^video\//.test(pickMedia.last||'')){kind=await askKind();if(!kind)return}const caption=prompt('وصف قصير للعمل (اختياري):')||'';await api('/me/portfolio','POST',{attachment_id:id,caption,kind});toast(kind==='reel'?'أُضيف إلى الريلز وسيظهر للجميع':'تم النشر وسيظهر للجميع في المنشورات')}await route()}catch(x){if(!/^لم تختر/.test(x.message))toast(x.message,1)}});
const report=async(type,id)=>{const reason=prompt('سبب البلاغ:');if(!reason)return;try{await api('/report','POST',{type,id,reason});toast('تم إرسال البلاغ')}catch(x){toast(x.message,1)}};
